use clap::{CommandFactory, Parser, Subcommand};
use serde::Serialize;
use standout::cli::{App, Dispatch, Output};
use standout::{embed_styles, embed_templates, handler};

#[derive(Parser)]
#[command(name = "brewlike")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers)]
enum Commands {
    #[dispatch(pure)]
    Probe,
}

#[derive(Serialize)]
struct Item {
    name: String,
}

mod handlers {
    use super::*;

