#[command(name = "brewlike")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers)]
enum Commands {
    #[dispatch(pure)]
    Probe,
    #[dispatch(pure)]
    Empty,
    #[dispatch(pure)]
    Ext,
    #[dispatch(pure)]
    Plain,
}

#[derive(Serialize)]
pub struct Item {
    pub name: String,
}

mod handlers {
    use super::*;

    #[handler]
    pub fn probe() -> Result<Output<Vec<Item>>, anyhow::Error> {
        Ok(Output::Render(vec![
            Item { name: "basalt".into() },
            Item { name: "granite".into() },
        ]))
    }

    #[handler]
    pub fn empty() -> Result<Output<Vec<Item>>, anyhow::Error> {
        Ok(Output::Render(vec![]))
    }

    #[handler]
    pub fn ext() -> Result<Output<Vec<Item>>, anyhow::Error> {
        Err(ExternalFailure::new(1, "brewlike: no formula found: obsidian\n")?.into())
    }

    #[handler]
    pub fn plain() -> Result<Output<Vec<Item>>, anyhow::Error> {
        Err(anyhow::anyhow!("brewlike: no formula found: obsidian"))
    }
}

