//! `brewlike` — a package-manager query client over one frozen cellar.

mod cellar;
mod view;

use clap::{CommandFactory, Parser, Subcommand};
use standout::cli::{App, Dispatch, ExternalFailure, Output};
use standout::{embed_styles, embed_templates, handler};

use crate::cellar::UnknownFormula;

#[derive(Parser)]
#[command(name = "brewlike", about = "Query the built-in cellar.")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Dispatch)]
#[dispatch(handlers = handlers)]
enum Commands {
    /// Every installed formula and the version installed.
    #[dispatch(pure)]
    List,

    /// What one formula is.
    #[dispatch(pure)]
    Info {
        /// The formula to describe.
        formula: String,
    },

    /// What a formula depends on, transitively.
    #[dispatch(pure)]
    Deps {
        /// Show the closure as a tree instead of a set.
        #[arg(long)]
        tree: bool,
        /// The formula to resolve.
        formula: String,
    },

    /// The installed formulae a newer version exists for.
    #[dispatch(pure)]
    Outdated {
        /// Restrict the query to these formulae.
        formula: Vec<String>,
    },
}

/// A domain error carrying `brewlike`'s own diagnostic.
///
/// Standout frames an ordinary handler error as `Error: {error}`; this spec
/// asks for `brewlike: no formula found: <name>` verbatim, so the diagnostic
/// travels through `ExternalFailure`, the one seam that hands stderr and the
/// exit status to the application untouched.
fn domain_error(error: UnknownFormula) -> anyhow::Error {
    let failure = ExternalFailure::new(1, format!("brewlike: {error}\n"))
        .expect("status 1 is nonzero");
    failure.into()
}

/// Look a formula up, or fail with the domain diagnostic.
fn require(name: &str) -> Result<&'static cellar::Formula, anyhow::Error> {
    cellar::find(name).ok_or_else(|| domain_error(UnknownFormula(name.to_string())))
}

mod handlers {
    use super::*;
    use crate::view::{DependencyNode, DependencyView, FormulaDetail, FormulaRecord};

    #[handler]
    pub fn list() -> Result<Output<Vec<FormulaRecord>>, anyhow::Error> {
        let records = cellar::all().iter().map(FormulaRecord::from).collect();
        Ok(Output::Render(records))
    }

    #[handler]
    pub fn info(#[arg] formula: String) -> Result<Output<FormulaDetail>, anyhow::Error> {
        Ok(Output::Render(FormulaDetail::from(require(&formula)?)))
    }

    #[handler]
    pub fn deps(
        #[flag] tree: bool,
        #[arg] formula: String,
    ) -> Result<Output<DependencyView>, anyhow::Error> {
        let formula = require(&formula)?;
        let view = if tree {
            DependencyView::Tree(DependencyNode::of(formula))
        } else {
            DependencyView::Names(
                cellar::closure(formula)
                    .into_iter()
                    .map(str::to_string)
                    .collect(),
            )
        };
        Ok(Output::Render(view))
    }

    #[handler]
    pub fn outdated(
        #[arg] formula: Vec<String>,
    ) -> Result<Output<Vec<FormulaRecord>>, anyhow::Error> {
        let formulae = cellar::outdated(&formula).map_err(domain_error)?;
        let records = formulae.into_iter().map(FormulaRecord::from).collect();
        Ok(Output::Render(records))
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let app = App::builder()
        .version(env!("CARGO_PKG_VERSION"))
        // Every command's document is a bare array or a bare record, so that
        // `--output json` has the root the contract names. A template can only
        // bind names in a map, so the same data is offered back to the
        // templates under one name. Context is template-only: the structured
        // modes still serialize the handler's own data.
        .context_fn("view", |ctx: &standout::context::RenderContext| {
            minijinja::Value::from_serialize(ctx.data)
        })
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme("default")
        .commands(Commands::dispatch_config())?
        .build()?;

    app.verify_command(&Cli::command())?;
    app.run(Cli::command(), std::env::args());
    Ok(())
}

