        .version(env!("CARGO_PKG_VERSION"))
        // Every command's document is a bare array or a bare record, so that
        // `--output json` has the root the contract names. A template can only
        // bind names in a map, so the same data is offered back to the
        // templates under one name. Context is template-only: the structured
        // modes still serialize the handler's own data.
        .context_fn("view", |ctx: &standout::context::RenderContext| {
            minijinja::Value::from_serialize(ctx.data)
        })
        .templates(embed_templates!("src/templates"))
        .styles(embed_styles!("src/styles"))
        .default_theme("default")
        .commands(Commands::dispatch_config())?
        .build()?;

    app.verify_command(&Cli::command())?;
    app.run(Cli::command(), std::env::args());
    Ok(())
}

